import numpy as np


def gradient_descent(grad, x0, s, n):
    x = np.asarray(x0, dtype=float)
    path = [x.copy()]
    for _ in range(n):
        x = x - s * np.asarray(grad(x), dtype=float)
        path.append(x.copy())
    return np.array(path)


def max_step(H):
    return 2 / np.linalg.eigvalsh(np.asarray(H, dtype=float)).max()
